def rep(old, new, count=1):
    global s
    n = s.count(old)
    assert n == count, "anchor count %d (want %d): %s" % (n, count, old[:160])
    s = s.replace(old, new)
    OLDS.append(old)


def blk(start, end, new):
    """replace s[start anchor : end anchor) (the end anchor stays)"""
    global s
    assert s.count(start) == 1, "start anchor count %d: %s" % (s.count(start), start[:120])
    i = s.index(start)
    j = s.index(end, i + len(start))
    old = s[i:j]
    s = s[:i] + new + s[j:]
    OLDS.append(old)


