M(mig, r"""
public static synchronized java.util.Properties migrate(String k) {
  try {
    java.nio.file.Path f = @PKG@.RbStore.DIR.resolve(k + ".properties");
    byte[] oldB = java.nio.file.Files.readAllBytes(f);
    java.util.Properties a = new java.util.Properties();
    a.load(new java.io.ByteArrayInputStream(oldB));
    if (!old(a)) return a;
    Object[] r = plan(a);
    java.util.Properties p = (java.util.Properties) r[0];
    java.nio.file.Path home = @PKG@.RbStore.DIR.getParent();
    java.nio.file.Path bd = home.resolve("vp-backup");
    if (TEST_FAIL_BACKUP) bd = home.resolve("vp-backup-blocked").resolve("x");
    java.nio.file.Files.createDirectories(bd, new java.nio.file.attribute.FileAttribute[0]);
    java.nio.file.Path bf = bd.resolve(k + ".properties." + stamp() + ".bak");
    java.nio.file.Files.write(bf, oldB, new java.nio.file.OpenOption[] { java.nio.file.StandardOpenOption.CREATE_NEW, java.nio.file.StandardOpenOption.WRITE });
    if (!java.util.Arrays.equals(java.nio.file.Files.readAllBytes(bf), oldB)) throw new java.io.IOException("the backup " + bf.getFileName() + " does not match the file");
    // fix round: the log line (with the Undo) BEFORE the write - a log failure leaves the file untouched (retried), never a migrated file
    // without its line; a failed write appends a second line saying so
    String line = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss").format(new java.util.Date()) + "\tSkyyRebirth @VERSION@\t" + k + "\tpoints left " + r[2] + " + spent " + r[3] + " -> +" + r[1] + " VP (now " + p.getProperty("vp") + "), " + r[4] + " old tree levels removed\tbackup vp-backup/" + bf.getFileName() + "\tUNDO: stop the server, copy that backup over players/" + k + ".properties, run SkyyRebirth 0.3.6";
    logLine(home, line);
    String e = TEST_FAIL_WRITE ? "test: the write fails" : @PKG@.RbStore.writeLocked(k, p);
    if (e != null) {
      try { logLine(home, new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss").format(new java.util.Date()) + "\tSkyyRebirth @VERSION@\t" + k + "\tTHE WRITE FAILED - the file is untouched, ignore the line above (the next read tries again): " + e); } catch (Throwable t2) { }
      throw new java.io.IOException(e);
    }
    MIGS.incrementAndGet();
    LAST = line;
    @PKG@.RbCfg.info("players/" + k + ".properties moved to Void Particles (0.4.0, once): " + r[2] + " points left + " + r[3] + " spent -> +" + r[1] + " VP; the old file is in vp-backup/" + bf.getFileName() + " (vp-migration.log has the Undo)");
    return p;
  } catch (Throwable t) {
    @PKG@.RbCfg.warn("players/" + k + ".properties could NOT be moved to Void Particles (0.4.0) - the file is untouched and not used until the next try (next read / start): " + t);
    return null;
  }
}""")
