# { rarity (1-4; 99 = not in acc:defs), "Admin (Display)" }
M(tree, r"""
public static Object[] charmInfo(String id) {
  Object d = @PKG@.RbCfg.bridge().get("acc:defs");
  if (d instanceof String && id != null) {
    String[] recs = ((String) d).split(",");
    for (int i = 0; i < recs.length; i++) {
      String[] f = recs[i].split(":");
      if (f.length >= 5 && f[3].equals(id)) {
        int t = 99;
        try { t = Integer.parseInt(f[2].trim()); } catch (Throwable x) { t = 99; }
        return new Object[] { Integer.valueOf(t), f[0] + " (" + f[4] + ")" };
      }
    }
  }
  String nm = id == null ? "?" : id;
  if (nm.startsWith("Skyy_")) nm = nm.substring(5);
  return new Object[] { Integer.valueOf(99), nm.replace('_', ' ') };
}""")
# the ids a respec would take (the need lowest-rarity charms of the bag, bag order breaks a tie; fix round: NEVER a charm outside acc:defs -
# rarity 99: the Furnace Charm tiers / Eternal Flame cost many ingots); null = the bag cannot be read; fewer than need = not enough
M(tree, r"""
public static String[] charmPick(java.util.UUID u, String k, int need) {
  java.util.function.Function f = bagFn();
  if (f == null || u == null) return null;
  Object r;
  try { r = f.apply(new Object[] { "list", u, k }); } catch (Throwable t) { return null; }
  if (!(r instanceof String)) return null;
  String l = ((String) r).trim();
  String[] ids = l.length() == 0 ? new String[0] : l.split(",");
  int[] tier = new int[ids.length];
  for (int i = 0; i < ids.length; i++) tier[i] = ((Integer) charmInfo(ids[i].trim())[0]).intValue();
  boolean[] used = new boolean[ids.length];
  int known = 0;
  for (int i = 0; i < ids.length; i++) if (tier[i] < 99) known++;
  int n = need < known ? need : known;
  String[] out = new String[n < 0 ? 0 : n];
  for (int j = 0; j < out.length; j++) {
    int best = -1;
    for (int i = 0; i < ids.length; i++) if (!used[i] && tier[i] < 99 && (best < 0 || tier[i] < tier[best])) best = i;
    used[best] = true;
    out[j] = ids[best].trim();
  }
  return out;
}""")
