M(page, r"""
public void fillNode(String k, java.util.Properties p) {
  int i = this.sel;
  int a = @PKG@.RbTree.NARM[i];
  int l = @PKG@.RbTree.lv(p, i);
  int mx = @PKG@.RbTree.NMAX[i];
  boolean hand = @PKG@.RbTree.NHAND[i] == 1;
  boolean full = @PKG@.RbTree.full(p, i);
  boolean maxed = l >= mx;
  this.buyKey = k;     // fix round: Buy sends exactly what this view shows
  this.buyLevel = l;
  this.buySel = i;
  this.nvName = @PKG@.RbTree.NNAME[i];
  this.nvSub = a == 0 ? "The Nexus - beside the black hole" : (hand ? "Hand arm - 6 skills share 5 ranks" : @PKG@.RbTree.ARM_NAME[a] + " arm");
  this.nvSubCol = @PKG@.RbTree.ARM_COL[a];
  boolean lv0 = @PKG@.RbTree.live(i);   // fix round: no live reader = not buyable ("coming with <mod>")
  this.nvLive = (lv0 ? "Works " : "Coming with " + @PKG@.RbTree.NRMOD[i] + ": works ") + @PKG@.RbTree.NLIVE[i];
  this.nvLevel = "Rank " + l + " / " + mx + (hand ? " - Hand " + @PKG@.RbTree.handTotal(p) + " / " + @PKG@.RbTree.HAND_MAX : "");
  this.nvNow = "Now: " + @PKG@.RbTree.fx(i, l);
  this.nvNext = maxed ? "Next: max rank reached" : (full ? "Next: Hand Echo is full (" + @PKG@.RbTree.HAND_MAX + " / " + @PKG@.RbTree.HAND_MAX + " ranks placed)" : "Next rank: " + @PKG@.RbTree.fx(i, l + 1));
  long c = @PKG@.RbTree.cost(p, i);
  long have = @PKG@.RbTree.held(p);
  this.nvCost = c < 0L ? "Cost: -" : "Cost: " + c + " VP";
  this.nvHave = "You hold " + @PKG@.RbTree.shortN(have) + " VP (+" + @PKG@.RbCfg.num(@PKG@.RbTree.keepPct(have)) + " % XP)";
  this.nvHaveCol = (c < 0L || have >= c) ? "@GOLD@" : "@BAD@";
  this.nvKeep = c < 0L ? "Keeping is the only choice left here." : "Keeping those " + c + " VP instead: +" + @PKG@.RbCfg.num(@PKG@.RbTree.keepPct(c)) + " % all XP";
  boolean busy = @PKG@.RbStore.BUSY.containsKey(k);
  this.canBuy = this.allowed && !busy && !this.pending && lv0 && c >= 0L && have >= c;
  String st = this.status;
  if (st == null) {
    if (this.pending) st = "=Working ...";
    else if (!this.allowed) st = "-Rebirth is switched off - only admins can buy while it is off.";
    else if (busy) st = "-A rebirth is running on this profile - try again after it.";
    else if (maxed) st = "=This node is at its max rank.";
    else if (full) st = "=Hand Echo is full: all " + @PKG@.RbTree.HAND_MAX + " ranks are placed.";
    else if (!lv0) st = "-" + @PKG@.RbTree.soon(i);
    else if (have < c) st = "-Not enough Void Particles yet (" + c + " VP).";
    else st = "=Press Buy to spend " + c + " VP.";
  }
  this.nvStatus = textOf(st);
  this.nvStCol = colorOf(st);
}""".replace("@GOOD@", GOOD).replace("@BAD@", BAD).replace("@GOLD@", GOLD))
# 0.4.0: what a respec would do now: the ptRe line, canRespec, respecShown (the spent VP the page shows), respecWhat (the charm names),
# respecIds (fix round: their ids). Only in the node view; the bag is asked at most every 3 s (fresh = the arming press asks it now)
M(page, r"""
public void fillRespec(String k, java.util.Properties p, boolean fresh) {
  long sp = @PKG@.RbTree.big(p, "vpSpent");
  int rk = @PKG@.RbTree.ranks(p);
  this.respecShown = sp;
  this.respecWhat = "";
  this.respecIds = "";
  boolean any = rk > 0 || sp > 0L;
  boolean ok = false;
  int need = @PKG@.RbCfg.RESPEC_CHARMS;
  if (!any) this.ptRe = "Respec: nothing spent yet";
  else if (need <= 0) { this.ptRe = "Respec: free (Server Setup)"; ok = true; }
  else if (@PKG@.RbTree.bagFn() == null) this.ptRe = "Respec: needs SkyyAccessories (Void Charms)";
  else {
    long now = System.currentTimeMillis();
    String[] ids;
    if (!fresh && this.respecPick != null && k.equals(this.respecPickK) && now >= this.respecPickAt && now - this.respecPickAt < 3000L) ids = this.respecPick;
    else { ids = @PKG@.RbTree.charmPick(this.me, k, need); this.respecPick = ids; this.respecPickK = k; this.respecPickAt = now; }
    if (ids == null || ids.length < need) this.ptRe = "Respec: your Void Charms hold " + (ids == null ? 0 : ids.length) + " of " + need;
    else {
      this.respecWhat = @PKG@.RbTree.charmNames(ids);
      this.respecIds = @PKG@.RbTree.charmKey(ids);
      String w = this.respecWhat.length() > 26 ? this.respecWhat.substring(0, 24) + " ..." : this.respecWhat;
      this.ptRe = "Respec: " + need + " Void Charm" + (need == 1 ? "" : "s") + " (" + w + ")";
      ok = true;
    }
  }
  this.canRespec = ok && this.allowed && !this.pending && !@PKG@.RbStore.BUSY.containsKey(k);
}""")
