_code = s.split('"""', 2)[2]
for _gone in ("RbMath.ARMS", "ARM_SKILL", "ARM_B", "echoPct", "echoed", "openRows", "ROW_NEED", "COST_GROWTH", "W_XP", "DUST_NODE", "dustArm",
              "RbTree.armIndex", "RbTree.refund", "RbTree.addPts", "RbAdminRefundCmd()", "RbMath.points"):
    assert _gone not in _code, "0.4.0: a 0.3 tree name is still used: " + _gone
assert (s.count("registerCommand("), s.count("registerSystem(")) == (CMD0, SYS0), "0.4.0: no command / system registration change"
assert s.count("@PKG@.RbMig.old(p)") == 2 and s.count("RbStore.peek(k)") == 2 and s.count("c.setProperty(\"v\", \"4\")") == 1
if os.path.exists(dst):
    os.remove(dst)
compile(s, dst, "exec")
open(dst, "wb").write(s.replace(LF, NL).encode("utf8"))
_a, _b = S0.split(LF), s.split(LF)
_hunks = [op for op in difflib.SequenceMatcher(None, _a, _b, autojunk=False).get_opcodes() if op[0] != "equal"]
print("wrote", dst, len(s), "chars;", len(_hunks), "diff hunks vs 0.3.6;", len(OLDS), "anchors")
